import{_ as t,C as i,o,c,a2 as a,b as s,w as d,a as r,E as l,a3 as p}from"./chunks/framework.DZUUNQ77.js";const f=JSON.parse('{"title":"Native 层 (JNI/Inline Hook)","description":"","frontmatter":{},"headers":[],"relativePath":"features/native-layer.md","filePath":"features/native-layer.md","lastUpdated":1784063681000}'),h={name:"features/native-layer.md"};function b(k,e,v,u,m,E){const n=i("Mermaid");return o(),c("div",null,[e[1]||(e[1]=a(`<h1 id="native-层-jni-inline-hook" tabindex="-1">Native 层 (JNI/Inline Hook) <a class="header-anchor" href="#native-层-jni-inline-hook" aria-label="Permalink to &quot;Native 层 (JNI/Inline Hook)&quot;">​</a></h1><p>VirtualXposed 有些事 Java 层做不到——拦截 libc 文件函数、hook native 方法、改 ART 内部结构。这些落在 <a href="https://github.com/android-security-engineer/VirtualXposed-skills/tree/vxp/lib/src/main/jni/" target="_blank" rel="noreferrer">src/main/jni/</a> 下，编译成 <code>libva++.so</code>，由 <code>NativeEngine</code> 加载。这一篇梳理 native 层的结构和职责。</p><h2 id="模块组成" tabindex="-1">模块组成 <a class="header-anchor" href="#模块组成" aria-label="Permalink to &quot;模块组成&quot;">​</a></h2><p><code>jni/Android.mk</code> 定义了 <code>va++</code> 共享库，源码分五个目录：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>jni/</span></span>
<span class="line"><span>├── Jni/             ← JNI 桥接（NativeEngine 的 native 方法实现）</span></span>
<span class="line"><span>│   └── VAJni.cpp</span></span>
<span class="line"><span>├── Foundation/      ← 核心功能</span></span>
<span class="line"><span>│   ├── IOUniformer.cpp   ← IO 重定向（hook libc 文件函数）</span></span>
<span class="line"><span>│   ├── VMPatch.cpp       ← ART 方法 hook（Java 方法层面的 native hook）</span></span>
<span class="line"><span>│   ├── SymbolFinder.cpp  ← 符号查找（找 libc/art 里的函数地址）</span></span>
<span class="line"><span>│   ├── Path.cpp          ← 重定向路径规则表</span></span>
<span class="line"><span>│   ├── SandboxFs.cpp     ← 沙箱文件系统视图</span></span>
<span class="line"><span>│   └── fake_dlfcn.cpp    ← 伪 dlopen/dlsym（绕过符号可见性限制）</span></span>
<span class="line"><span>├── Substrate/       ← inline hook 库（x86/通用）</span></span>
<span class="line"><span>│   ├── SubstrateHook.cpp</span></span>
<span class="line"><span>│   ├── SubstratePosixMemory.cpp</span></span>
<span class="line"><span>│   ├── hde64.c             ← 64位指令反汇编</span></span>
<span class="line"><span>│   └── SubstrateDebug.cpp</span></span>
<span class="line"><span>├── A64Inlinehook/   ← arm64 专用 inline hook</span></span>
<span class="line"><span>│   └── And64InlineHook.cpp</span></span>
<span class="line"><span>└── fb/              ← Facebook 的 JNI 异常处理库（lyra）</span></span>
<span class="line"><span>    ├── jni/...、lyra/...</span></span>
<span class="line"><span>    ├── assert.cpp / log.cpp / onload.cpp</span></span>
<span class="line"><span>    └── Android.mk</span></span></code></pre></div><p>这五部分从上到下是“Java 桥接 → 核心功能 → 底层 hook 引擎”的分层：</p>`,6)),(o(),s(p,null,{default:d(()=>[l(n,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20JE%5B%22Java%20%E5%B1%82%3Cbr%2F%3ENativeEngine%22%5D%20--%3E%7C%22JNI%22%7C%20JNI%5B%22Jni%2F%3Cbr%2F%3EVAJni.cpp%22%5D%0A%20%20JNI%20--%3E%20FOUND%5B%22Foundation%2F%20(%E6%A0%B8%E5%BF%83%E5%8A%9F%E8%83%BD)%22%5D%0A%20%20FOUND%20--%3E%20IOU%5B%22IOUniformer%3Cbr%2F%3Elibc%20%E6%96%87%E4%BB%B6%E5%87%BD%E6%95%B0%20hook%22%5D%0A%20%20FOUND%20--%3E%20VMP%5B%22VMPatch%3Cbr%2F%3EJava%20native%20%E6%96%B9%E6%B3%95%20hook%22%5D%0A%20%20FOUND%20--%3E%20SF%5B%22SymbolFinder%3Cbr%2F%3EELF%20%E7%AC%A6%E5%8F%B7%E6%9F%A5%E6%89%BE%22%5D%0A%20%20FOUND%20--%3E%20PATH%5B%22Path%20%2F%20SandboxFs%3Cbr%2F%3E%E9%87%8D%E5%AE%9A%E5%90%91%E8%A7%84%E5%88%99%E8%A1%A8%22%5D%0A%20%20IOU%20--%3E%20HOOK%5B%22inline%20hook%20%E5%BC%95%E6%93%8E%22%5D%0A%20%20VMP%20--%3E%20HOOK%0A%20%20HOOK%20--%3E%20SUB%5B%22Substrate%2F%3Cbr%2F%3Ex86_64%20%2B%20hde64%20%E5%8F%8D%E6%B1%87%E7%BC%96%22%5D%0A%20%20HOOK%20--%3E%20A64%5B%22A64Inlinehook%2F%3Cbr%2F%3Earm64%20PC%20%E7%9B%B8%E5%AF%B9%E5%AF%BB%E5%9D%80%E9%87%8D%E5%AE%9A%E4%BD%8D%22%5D%0A%20%20FOUND%20-.-%3E%7C%22%E5%B4%A9%E6%BA%83%E5%8F%AF%E8%AF%BB%E5%A0%86%E6%A0%88%22%7C%20FB%5B%22fb%2F%3Cbr%2F%3Elyra%20%E5%BC%82%E5%B8%B8%E5%A4%84%E7%90%86%22%5D%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<p>上层 <code>Jni</code> 把 Java 调用翻译成 Foundation 的操作，Foundation 依赖底层 inline hook 引擎去改写真实函数指令。</p><h2 id="jni-桥接-vajni-cpp" tabindex="-1">JNI 桥接：VAJni.cpp <a class="header-anchor" href="#jni-桥接-vajni-cpp" aria-label="Permalink to &quot;JNI 桥接：VAJni.cpp&quot;">​</a></h2><p><code>Jni/VAJni.cpp</code> 实现了 <code>NativeEngine</code> 声明的所有 <code>native</code> 方法，把 Java 调用转发到 Foundation 层：</p><table tabindex="0"><thead><tr><th>NativeEngine 方法</th><th>VAJni 实现</th></tr></thead><tbody><tr><td><code>nativeIORedirect(orig, new)</code></td><td>注册到 <code>Path</code> 规则表</td></tr><tr><td><code>nativeIOWhitelist(path)</code></td><td>加白名单</td></tr><tr><td><code>nativeIOForbid(path)</code></td><td>加禁止</td></tr><tr><td><code>nativeEnableIORedirect(soPath, api, preview)</code></td><td>调 <code>IOUniformer</code> 启动 hook</td></tr><tr><td><code>nativeGetRedirectedPath(orig)</code> / <code>nativeReverseRedirectedPath</code></td><td>查规则做路径转换</td></tr><tr><td><code>nativeLaunchEngine(methods, hostPkg, isArt, api, cameraType)</code></td><td>调 <code>VMPatch</code> hook 指定 native 方法</td></tr><tr><td><code>disableJit(api)</code></td><td>关闭 JIT</td></tr></tbody></table><p><code>onLoad</code> 里 <code>fb/onload.cpp</code> 注册 lyra 的异常处理，让 native 崩溃时能生成可读堆栈。</p><h2 id="iouniformer-io-重定向核心" tabindex="-1">IOUniformer：IO 重定向核心 <a class="header-anchor" href="#iouniformer-io-重定向核心" aria-label="Permalink to &quot;IOUniformer：IO 重定向核心&quot;">​</a></h2><p><a href="./io-redirect">IO 重定向</a> 已详述，这里补 native 视角。<code>IOUniformer.cpp</code> 的套路：</p><ol><li>用 <code>SymbolFinder</code> 在 <code>/system/lib(64)/libc.so</code> 里找到 <code>open</code>/<code>openat</code>/<code>stat</code>/<code>lstat</code>/<code>access</code>/<code>faccessat</code>/<code>readlink</code>/<code>readlinkat</code>/<code>fopen</code>/<code>mkdir</code>/<code>rmdir</code>/<code>readdir</code>/<code>rename</code>/<code>symlink</code>/<code>unlink</code>/<code>chmod</code>/<code>chown</code> 等函数的真实地址。</li><li>用 inline hook（Substrate 或 And64InlineHook）把函数入口指令改写，跳到自己的 wrapper。</li><li>wrapper 里调 <code>Path</code> 查规则：路径命中 <code>redirectDirectory</code> 规则就替换，命中 <code>whitelist</code> 就跳过，命中 <code>forbid</code> 就返回 <code>EACCES</code>。</li><li>处理后的路径调真实 libc 函数。</li></ol><p><code>SandboxFs.cpp</code> 提供更高层的沙箱视图（目录枚举过滤等），<code>Path.cpp</code> 维护 <code>origPath → newPath</code> 的映射和匹配（按最长前缀）。</p><h2 id="symbolfinder-与-fake-dlfcn-找符号" tabindex="-1">SymbolFinder 与 fake_dlfcn：找符号 <a class="header-anchor" href="#symbolfinder-与-fake-dlfcn-找符号" aria-label="Permalink to &quot;SymbolFinder 与 fake_dlfcn：找符号&quot;">​</a></h2><p>hook 一个函数前要先拿到它的地址。正常 <code>dlsym</code> 只能找导出符号，且 Android 对系统库的符号可见性有限制。VirtualXposed 用两种手段：</p><ul><li><strong>SymbolFinder</strong>：直接解析 ELF 文件（<code>.dynsym</code>/<code>.symtab</code> 表）找符号地址，不依赖 <code>dlsym</code>，能找到未导出的内部符号。</li><li><strong>fake_dlfcn</strong>：实现一套“伪 dlopen/dlsym”，绕过系统的命名空间和可见性限制，可以像操作普通库一样查找 <code>libc.so</code>/<code>libart.so</code> 里的符号。</li></ul><p>这让 VirtualXposed 能 hook 到 libc 的内部函数和 ART 的内部方法。</p><h2 id="vmpatch-art-方法-hook" tabindex="-1">VMPatch：ART 方法 hook <a class="header-anchor" href="#vmpatch-art-方法-hook" aria-label="Permalink to &quot;VMPatch：ART 方法 hook&quot;">​</a></h2><p><code>nativeLaunchEngine</code> 传入的 <code>methods</code> 是几个 Java native 方法（<code>openDexFileNative</code>、<code>Camera.native_setup</code>、<code>AudioRecord.native_check_permission</code>）。<code>VMPatch.cpp</code> 对这些方法做 hook：</p><ul><li>把 Java native 方法的实现替换成自己的回调。</li><li>回调里能改参数（如 <code>onOpenDexFileNative</code> 改 odex 输出路径）、改返回值、加权限检查。</li></ul><p>这和 epic 的 ART 方法 hook 不同——epic hook 的是任意 Java 方法（包括非 native 的），<code>VMPatch</code> 主要针对 native 方法。两者互补：epic 管 Xposed 模块的方法 hook，VMPatch 管引擎自己需要的 native 方法 hook。</p><h2 id="inline-hook-库" tabindex="-1">inline hook 库 <a class="header-anchor" href="#inline-hook-库" aria-label="Permalink to &quot;inline hook 库&quot;">​</a></h2><table tabindex="0"><thead><tr><th>库</th><th>用途</th></tr></thead><tbody><tr><td><code>SubstrateHook</code></td><td>通用 inline hook，基于指令重写 + 跳转。<code>SubstratePosixMemory</code> 处理内存权限（<code>mprotect</code>）。<code>hde64</code> 反汇编 64 位指令确定要复制的指令长度。</td></tr><tr><td><code>And64InlineHook</code></td><td>arm64 专用的 inline hook 实现，处理 ARM64 指令集的 PC 相对寻址重定位。</td></tr></tbody></table><p>为什么用两个？因为 inline hook 要把目标函数开头的几条指令替换成跳转指令，而 ARM64 和 x86_64 指令长度/寻址方式不同，需要各自专用的实现。当前构建只产出 <code>arm64-v8a</code> 和 <code>x86_64</code> 两个 ABI（见 <code>lib/build.gradle</code> 的 <code>abiFilters</code>）。</p><h2 id="_64-位定位" tabindex="-1">64 位定位 <a class="header-anchor" href="#_64-位定位" aria-label="Permalink to &quot;64 位定位&quot;">​</a></h2><p><code>app/build.gradle</code> 里 <code>applicationId &quot;io.va.exposed64&quot;</code>，<code>abiFilters &quot;arm64-v8a&quot;, &quot;x86_64&quot;</code>——这是个 64 位包。原因：</p><ul><li>Android 5.0+ 支持 64 位 ART，64 位能 hook 到 64 位进程里的方法。</li><li><code>exposed64</code> 的命名暗示这是为 64 位优化的版本。</li><li>不含 32 位 ABI，所以 32 位设备/纯 32 位 App 不适用。</li></ul><h2 id="native-hook-vs-java-hook-的分工" tabindex="-1">native hook vs Java hook 的分工 <a class="header-anchor" href="#native-hook-vs-java-hook-的分工" aria-label="Permalink to &quot;native hook vs Java hook 的分工&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>用哪个</th></tr></thead><tbody><tr><td>拦截系统服务方法（AMS/PMS/Location...）</td><td>Java 层 <code>MethodProxy</code> 动态代理</td></tr><tr><td>拦截 libc 文件函数</td><td>native <code>IOUniformer</code></td></tr><tr><td>拦截 Java native 方法（openDexFile/Camera/Audio）</td><td>native <code>VMPatch</code></td></tr><tr><td>拦截任意 Java 方法（Xposed 模块用的）</td><td>epic（ART inline hook）</td></tr><tr><td>改私有字段（mH、gDefault、Build.SERIAL）</td><td><code>mirror</code> 反射 + <code>free_reflection</code></td></tr></tbody></table><p>四层各管一段，共同覆盖目标 App 的所有可拦截路径。</p><h2 id="风控提示" tabindex="-1">风控提示 <a class="header-anchor" href="#风控提示" aria-label="Permalink to &quot;风控提示&quot;">​</a></h2><p>native hook 会在进程里留下可检测的痕迹（被改写的指令、额外的 .so）。反作弊引擎能扫到 <code>libva++.so</code>、检测到 inline hook 的特征。这也是为什么游戏/支付类 App 在 VirtualXposed 里容易被识别。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><code>libva++.so</code> 由 <code>Jni</code>/<code>Foundation</code>/<code>Substrate</code>/<code>A64Inlinehook</code>/<code>fb</code> 五部分组成。</li><li><code>IOUniformer</code> 在 native 层 hook libc 文件函数实现路径重定向。</li><li><code>SymbolFinder</code>/<code>fake_dlfcn</code> 绕过符号可见性限制找地址。</li><li><code>VMPatch</code> hook 特定 Java native 方法（openDex/Camera/Audio）。</li><li>inline hook 用 Substrate（x86_64）和 And64InlineHook（arm64）两套。</li><li>与 Java 层 <code>MethodProxy</code>、<code>mirror</code>、epic 分工互补。</li></ul><p>native 层是 VirtualXposed 能“骗过到底层”的根基。接下来进入 <a href="./../xposed/how-it-works">Xposed 集成</a>，看 epic 怎么在这个虚拟进程里实现免 Root 的方法 Hook。</p>',31))])}const F=t(h,[["render",b]]);export{f as __pageData,F as default};
